/** @param {NS} ns */
export async function main(ns) {
  const servers = [];
  let queue = ['home'];
  let visited = new Set(['home']);

  // BFS to find all servers
  while (queue.length > 0) {
    const host = queue.shift();
    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
        servers.push(neighbor);
      }
    }
  }

  // Attempt to gain root on all servers
  for (const server of servers) {
    if (!ns.hasRootAccess(server)) {
      const ports = ns.getServerNumPortsRequired(server);
      if (ports <= 0) {
        ns.nuke(server);
      }
    }
  }

  // Filter hackable servers
  const hackable = servers.filter(s => {
    if (!ns.hasRootAccess(s)) return false;
    const maxMoney = ns.getServerMaxMoney(s);
    return maxMoney > 0;
  });

  // Sort by money potential (descending)
  hackable.sort((a, b) => {
    const moneyA = ns.getServerMaxMoney(a);
    const moneyB = ns.getServerMaxMoney(b);
    return moneyB - moneyA;
  });

  // Main hacking loop - no expensive calls
  while (true) {
    for (const server of hackable) {
      // Quick hack without analysis
      await ns.hack(server);
    }
    await ns.sleep(100);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const targets = new Set();
  let scanned = new Set();

  // Initial scan
  const queue = ['home'];
  while (queue.length > 0) {
    const server = queue.shift();
    if (scanned.has(server)) continue;
    scanned.add(server);

    const neighbors = ns.scan(server);
    for (const neighbor of neighbors) {
      if (!scanned.has(neighbor)) {
        queue.push(neighbor);
        targets.add(neighbor);
      }
    }
  }

  // Main loop
  while (true) {
    let best = null;
    let bestScore = -1;

    // Find best target
    for (const target of targets) {
      if (ns.hasRootAccess(target)) {
        const money = ns.getServerMoneyAvailable(target);
        const sec = ns.getServerSecurityLevel(target);
        if (money > 0) {
          const score = money / (sec + 1);
          if (score > bestScore) {
            bestScore = score;
            best = target;
          }
        }
      }
    }

    if (!best) {
      await ns.sleep(1000);
      continue;
    }

    const baseSec = ns.getServerBaseSecurityLevel(best);
    const currSec = ns.getServerSecurityLevel(best);
    const money = ns.getServerMoneyAvailable(best);

    if (currSec > baseSec + 5) {
      await ns.weaken(best);
    } else if (money < 1000000) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }
  }
}

